package dev.eugheist.tc4modern;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.item.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.inventory.ClickType;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import thaumcraft.api.aspects.*;
@EventBusSubscriber(modid=TC4Modern.MODID,value=net.neoforged.api.distmarker.Dist.CLIENT)
final class HoverHarnessAudit {
 static int ticks;static volatile boolean ready,flight,off,on,finished;static ItemStack armor;static final BlockPos POS=InfusionAudit.POS;
 static final List<BlockPos> PEDS=new ArrayList<>(TravellerBootsAudit.PEDESTALS);
 static {PEDS.addAll(List.of(POS.offset(-5,-2,0),POS.offset(5,-2,0),POS.offset(0,-2,5)));}
 static void check(boolean b,String s){if(!b)throw new IllegalStateException("TC4_HOVER FAIL "+s);System.out.println("TC4_HOVER PASS "+s);}
 static ItemStack fueled(ServerPlayer p,int amount){var out=new ItemStack(HoverHarness.harness());var jar=new ItemStack(EssentiaDevices.JAR.get());EssentiaItems.setAspects(jar,new AspectList().add(Aspect.ENERGY,amount));HoverHarness.store(out,jar,p.registryAccess());return out;}
 static void prepare(ServerPlayer p){InfusionAudit.prepare(p);InfusionAudit.matrix.logic.crafting=false;p.serverLevel().getEntitiesOfClass(ItemEntity.class,new net.minecraft.world.phys.AABB(POS).inflate(25)).forEach(Entity::discard);for(int i=0;i<4;i++)BaublesInventory.of(p).setItem(i,ItemStack.EMPTY);p.setItemSlot(EquipmentSlot.CHEST,ItemStack.EMPTY);p.setItemSlot(EquipmentSlot.FEET,ItemStack.EMPTY);HoverHarness.STATES.remove(p);
  var sample=fueled(p,2);for(int i=0;i<360;i++)checkQuiet(HoverHarness.expend(p,sample));check(HoverHarness.fuel(HoverHarness.jar(sample,p.registryAccess()))==2&&NoteData.tag(sample).getShort("charge")==360,"360 original charge increments before consuming fuel");check(HoverHarness.expend(p,sample)&&HoverHarness.fuel(HoverHarness.jar(sample,p.registryAccess()))==1&&NoteData.tag(sample).getShort("charge")==0,"361st call consumes one Potentia");for(int i=0;i<360;i++)checkQuiet(HoverHarness.expend(p,sample));check(!HoverHarness.expend(p,sample)&&HoverHarness.fuel(HoverHarness.jar(sample,p.registryAccess()))==0&&!HoverHarness.jar(sample,p.registryAccess()).isEmpty(),"last fuel unit stops flight but preserves empty jar");
  BaublesInventory.of(p).setItem(3,new ItemStack(HoverHarness.girdle()));sample=fueled(p,2);for(int i=0;i<288;i++)checkQuiet(HoverHarness.expend(p,sample));check(HoverHarness.fuel(HoverHarness.jar(sample,p.registryAccess()))==2&&HoverHarness.expend(p,sample)&&HoverHarness.fuel(HoverHarness.jar(sample,p.registryAccess()))==1,"original girdle paradox uses fuel every289calls");p.fallDistance=4;((HoverHarness.Girdle)HoverHarness.girdle()).onWornTick(BaublesInventory.of(p).getItem(3),p);check(Math.abs(p.fallDistance-3.67)<.0001,"girdle reduces fall distance .33");BaublesInventory.of(p).setItem(3,ItemStack.EMPTY);
  sample=new ItemStack(HoverHarness.harness());p.setItemSlot(EquipmentSlot.CHEST,sample);check(!HoverHarness.set(p,true),"cannot activate without fuel");check(sample.getMaxDamage()==400&&((ArmorItem)sample.getItem()).getDefense()==2&&sample.getEnchantmentValue()==25,"original400durability2defence25enchantability");check(((HoverHarness.Harness)sample.getItem()).getVisDiscount(sample,p,Aspect.AIR)==5&&((HoverHarness.Harness)sample.getItem()).getVisDiscount(sample,p,Aspect.FIRE)==2,"original5air2other vis discount");var haste=p.registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.ENCHANTMENT).getOrThrow(BasicsEnchantments.HASTE);check(haste.value().canEnchant(sample),"haste can enchant harness");
  for(var key:List.of("HoverHarness","HoverGirdle")){var r=InfusionItemRecipes.all().stream().filter(x->x.key().equals(key)).findFirst().orElseThrow();check(InfusionItemRecipes.match(r.componentStacks(),new ItemStack(r.central().get()),Set.of(r.research()))==r&&InfusionItemRecipes.match(r.componentStacks(),new ItemStack(r.central().get()),Set.of())==null,"original infusion ingredients and research "+key);}
  var wand=p.getInventory().items.stream().filter(WandData::isWand).findFirst().orElseThrow().copy();p.getInventory().clearContent();p.getInventory().setItem(8,wand);p.setItemSlot(EquipmentSlot.CHEST,ItemStack.EMPTY);armor=new ItemStack(HoverHarness.harness());p.getInventory().setItem(0,armor);p.getInventory().selected=0;var jar=new ItemStack(EssentiaDevices.JAR.get());EssentiaItems.setAspects(jar,new AspectList().add(Aspect.ENERGY,20));p.getInventory().setItem(1,jar);armor.use(p.level(),p,net.minecraft.world.InteractionHand.MAIN_HAND);check(p.containerMenu instanceof HoverHarness.Menu,"actual rightclick opens harness menu");var menu=(HoverHarness.Menu)p.containerMenu;var wrong=new ItemStack(EssentiaDevices.JAR.get());EssentiaItems.setAspects(wrong,new AspectList().add(Aspect.AIR,10));check(menu.slots.get(0).mayPlace(jar)&&!menu.slots.get(0).mayPlace(wrong)&&!menu.slots.get(0).mayPlace(new ItemStack(Items.DIRT)),"menu accepts only Potentia jar");check(!menu.quickMoveStack(p,29).isEmpty()&&menu.contents.getItem(0).getCount()==1&&p.getInventory().getItem(1).isEmpty(),"actual shift-click moves exactly one jar");System.out.println("TC4_HOVER lock held="+menu.held+" pickup="+menu.slots.get(28).mayPickup(p)+" before="+p.getInventory().getItem(0));menu.clicked(28,1,ClickType.THROW,p);System.out.println("TC4_HOVER lock after="+p.getInventory().getItem(0)+" armor="+armor);check(p.getInventory().getItem(0).is(HoverHarness.harness())&&p.getInventory().getItem(0).getCount()==1,"held harness slot locked against dropping");ready=true;
 }
 static void checkQuiet(boolean b){if(!b)throw new IllegalStateException("TC4_HOVER unexpected early fuel exhaustion");}
 static void start(ServerPlayer p){p.closeContainer();check(HoverHarness.fuel(HoverHarness.jar(armor,p.registryAccess()))==20,"menu close preserves full20Potentia jar");p.getInventory().setItem(0,ItemStack.EMPTY);p.setItemSlot(EquipmentSlot.CHEST,armor);p.getAbilities().mayfly=false;p.getAbilities().flying=false;p.connection.teleport(POS.getX()+7,POS.getY()+3,POS.getZ()-8,40,25);check(HoverHarness.set(p,true),"server starts paid hover with vanilla mayfly false");p.fallDistance=8;HoverHarness.tick(new net.neoforged.neoforge.event.tick.PlayerTickEvent.Pre(p));check(p.getAbilities().flying&&p.fallDistance==0,"hover enables flight and resets fall distance");
  var r=InfusionItemRecipes.all().stream().filter(x->x.key().equals("HoverHarness")).findFirst().orElseThrow();var l=p.serverLevel();((InfusionContent.PedestalEntity)l.getBlockEntity(POS.below(2))).setItem(new ItemStack(Items.LEATHER_CHESTPLATE));var parts=r.componentStacks();for(int i=0;i<9;i++){l.setBlock(PEDS.get(i),InfusionContent.PEDESTAL.get().defaultBlockState(),3);((InfusionContent.PedestalEntity)l.getBlockEntity(PEDS.get(i))).setItem(parts.get(i));}for(int dx:new int[]{-1,1})l.setBlock(POS.offset(dx,-2,-4),net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),3);int i=0;for(var a:r.aspects().getAspects()){var pos=POS.offset(i++*2-3,-2,-5);l.setBlock(pos,EssentiaDevices.JAR.get().defaultBlockState(),3);var jar=(WardedJarEntity)l.getBlockEntity(pos);jar.state.aspect=a;jar.state.amount=r.aspects().getAmount(a);jar.changed();}InfusionAudit.click(p,p.getInventory().getItem(8));check(InfusionAudit.matrix.logic.crafting&&InfusionAudit.matrix.logic.recipeEssentia.visSize()==112&&InfusionAudit.matrix.logic.recipeIngredients.size()==9,"actual wand starts112essentia9component harness infusion");flight=true;
 }
 static void finish(ServerPlayer p){var l=p.serverLevel();check(!InfusionAudit.matrix.logic.crafting&&((InfusionContent.PedestalEntity)l.getBlockEntity(POS.below(2))).item().is(HoverHarness.harness()),"natural altar creates harness");for(var pos:PEDS)check(((InfusionContent.PedestalEntity)l.getBlockEntity(pos)).item().isEmpty(),"original component consumed "+pos);for(int dx:new int[]{-3,-1,1,3})check(((WardedJarEntity)l.getBlockEntity(POS.offset(dx,-2,-5))).state.amount==0,"exact essentia consumed "+dx);p.setItemSlot(EquipmentSlot.CHEST,ItemStack.EMPTY);HoverHarness.tick(new net.neoforged.neoforge.event.tick.PlayerTickEvent.Pre(p));check(!p.getAbilities().flying&&!HoverHarness.active(p),"unequipping harness stops hover");finished=true;}
 static void key(){net.minecraft.client.KeyMapping.click(com.mojang.blaze3d.platform.InputConstants.Type.KEYSYM.getOrCreate(org.lwjgl.glfw.GLFW.GLFW_KEY_H));}
 @SubscribeEvent static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post e){if(!Boolean.getBoolean("tc4modern.hoverAuditOnly"))return;var mc=net.minecraft.client.Minecraft.getInstance();if(mc.player==null||mc.level==null)return;ticks++;var s=mc.getSingleplayerServer();var id=mc.player.getUUID();if(ticks==80)s.execute(()->prepare(s.getPlayerList().getPlayer(id)));if(ticks==100){check(ready&&mc.screen instanceof HoverHarnessClient.Screen,"actual client fuel screen");LiquidDeathAudit.shot(mc,"hover-harness-fuel-menu.png");}if(ticks==115)s.execute(()->start(s.getPlayerList().getPlayer(id)));if(ticks==140){check(flight&&HoverHarness.active(mc.player),"paid flight reaches client");mc.options.setCameraType(net.minecraft.client.CameraType.THIRD_PERSON_BACK);}if(ticks==160){check(HoverHarnessClient.modelsRendered>0&&HoverHarnessClient.ringsRendered>0,"original harness OBJ and animated ring model render");LiquidDeathAudit.shot(mc,"hover-harness-flying.png");}if(ticks==180)key();if(ticks==195){check(!HoverHarness.active(mc.player),"real H key disables hover");s.execute(()->{check(!HoverHarness.active(s.getPlayerList().getPlayer(id)),"H disable reaches server");off=true;});}if(ticks==205)key();if(ticks==220){check(off&&HoverHarness.active(mc.player),"real H key reenables hover");s.execute(()->{check(HoverHarness.active(s.getPlayerList().getPlayer(id)),"H enable reaches server");on=true;});}if(ticks==450){check(on&&HoverHarnessClient.boltsSpawned>0,"original translucent type6 lightning spawned");LiquidDeathAudit.shot(mc,"hover-harness-lightning.png");}if(ticks==1900)s.execute(()->finish(s.getPlayerList().getPlayer(id)));if(ticks>=1915&&(ticks-1915)%15==0){check(finished,"server infusion and unequip complete");int index=(ticks-1915)/15;if(index>=3){mc.stop();return;}var inv=mc.player.getInventory();var book=new ThaumonomiconScreen(new ThaumonomiconMenu(0,inv),inv,net.minecraft.network.chat.Component.empty());book.auditOpen(thaumcraft.api.research.ResearchCategories.getResearch(index<2?"HOVERHARNESS":"HOVERGIRDLE"),index==1?2:0);mc.setScreen(book);}if(ticks>=1920&&(ticks-1920)%15==0)LiquidDeathAudit.shot(mc,"hover-harness-book-"+(ticks-1920)/15+".png");}
}
